<?php
// Read input
$line = trim(fgets(STDIN));
$parts = explode(' ', $line);
$r = (int)$parts[0];
$x = (int)$parts[1];
$y = (int)$parts[2];
$x2 = (int)$parts[3];
$y2 = (int)$parts[4];

// Calculate the squared distance between the two centers
$dx = $x2 - $x;
$dy = $y2 - $y;
$distSq = $dx * $dx + $dy * $dy;

// If the distance is 0, no steps needed
if ($distSq == 0) {
    echo 0;
    exit;
}

// The maximum distance the center can move in one step is 2*r
// So the minimum number of steps is ceil(distance / (2*r))
// We need to compute ceil(sqrt(distSq) / (2*r))

// To avoid floating point issues, we can use integer arithmetic
// Let d = sqrt(distSq), we need ceil(d / (2*r))
// This is equivalent to ceil(sqrt(distSq) / (2*r))

// We can compute this as:
// steps = ceil(sqrt(distSq) / (2*r))
// = ceil(sqrt(distSq) / (2*r))

// To avoid floating point, we can check:
// Let k = 2*r
// We want the smallest integer n such that n * k >= sqrt(distSq)
// Which is equivalent to (n * k)^2 >= distSq
// So n = ceil(sqrt(distSq) / k)

// We can compute this using integer square root
function isqrt($n) {
    if ($n < 0) return -1;
    if ($n == 0) return 0;
    $x = (int)($n / 2);
    if ($x < 1) return 1;
    while (true) {
        $y = (int)(($x + (int)($n / $x)) / 2);
        if ($y >= $x) {
            return $x;
        }
        $x = $y;
    }
}

$dist = isqrt($distSq);
// Check if dist^2 == distSq, if not, dist is floor, so actual distance is between dist and dist+1
// We need ceil(dist / (2*r))

$step = 2 * $r;

// We need to find the smallest integer n such that n * step >= sqrt(distSq)
// i.e., (n * step)^2 >= distSq

// Let's try n = floor(dist / step) and check
$n = (int)($dist / $step);

// Check if n * step >= sqrt(distSq), i.e., (n*step)^2 >= distSq
if ($n * $step * $n * $step >= $distSq) {
    // But we need to make sure n is at least 1 if distSq > 0
    if ($n == 0 && $distSq > 0) {
        $n = 1;
    }
    echo $n;
} else {
    echo $n + 1;
}
