$x = (int)$parts[1];
$y = (int)$parts[2];
$x2 = (int)$parts[3];
$y2 = (int)$parts[4];

// Calculate the distance between original and destination centers
$dx = $x2 - $x;
$dy = $y2 - $y;
$distSq = $dx * $dx + $dy * $dy;

// If distance is 0, no steps needed
if ($distSq == 0) {
    echo 0;
    exit;
}

// The maximum distance the center can move in one step is 2*r (diameter)
// Because when you pin a point on the border and rotate, the center moves
// along a circle of radius r around the pin. The maximum displacement
// of the center in one rotation is 2*r (when rotating 180 degrees).

// So minimum steps = ceil(dist / (2*r))
$dist = sqrt($distSq);
$maxMove = 2 * $r;

$steps = (int)ceil($dist / $maxMove);

echo $steps;
?>
